import importlib.util
code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 2
    for r in range(h - 1):
        for c in range(w - 1):
            if grid[r][c] == grid[r+1][c] == grid[r][c+1] == grid[r+1][c+1] == 2:
                points = {
                    "NW": (r-1, c-1),
                    "NE": (r-1, c+2),
                    "SW": (r+2, c-1),
                    "SE": (r+2, c+2),
                }
                colors = {k: grid[rr][cc] if 0 <= rr < h and 0 <= cc < w else 0
                          for k, (rr, cc) in points.items()}
                assignments = {"NW": colors["SW"], "NE": colors["NW"],
                               "SW": colors["SE"], "SE": colors["NE"]}
                directions = {"NW": (-1, -1), "NE": (-1, 1),
                              "SW": (1, -1), "SE": (1, 1)}
                for k, (rr, cc) in points.items():
                    color = assignments[k]
                    dr, dc = directions[k]
                    while color and 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out
'''
